from lib import *
LES = [
L("invtrig", "D", "Inverse trig forms", "รูปตรีโกณผกผัน",
 [T("<b>Theorem.</b> For $a>0$: $$\\int\\frac{dx}{a^{2}+x^{2}}=\\frac1a\\arctan\\frac xa+C\\ \\ \\text{on }\\mathbb{R},\\qquad \\int\\frac{dx}{\\sqrt{a^{2}-x^{2}}}=\\arcsin\\frac xa+C\\ \\ \\text{on }(-a,a).$$",
    "<b>ทฤษฎีบท</b> สำหรับ $a>0$: $$\\int\\frac{dx}{a^{2}+x^{2}}=\\frac1a\\arctan\\frac xa+C\\ \\ \\text{บน }\\mathbb{R},\\qquad \\int\\frac{dx}{\\sqrt{a^{2}-x^{2}}}=\\arcsin\\frac xa+C\\ \\ \\text{บน }(-a,a)$$"),
  T("<b>Completing the square.</b> If $4c-b^{2}>0$ then $x^{2}+bx+c=\\left(x+\\tfrac b2\\right)^{2}+k^{2}$ with $k=\\tfrac12\\sqrt{4c-b^{2}}$, so $\\displaystyle\\int\\frac{dx}{x^{2}+bx+c}=\\frac1k\\arctan\\frac{x+\\frac b2}{k}+C$.",
    "<b>ทำเป็นกำลังสองสมบูรณ์</b> ถ้า $4c-b^{2}>0$ แล้ว $x^{2}+bx+c=\\left(x+\\tfrac b2\\right)^{2}+k^{2}$ โดย $k=\\tfrac12\\sqrt{4c-b^{2}}$ ดังนั้น $\\displaystyle\\int\\frac{dx}{x^{2}+bx+c}=\\frac1k\\arctan\\frac{x+\\frac b2}{k}+C$")],
 [S("<b>Inverse function theorem.</b> If $f$ is differentiable and strictly monotone on an open interval with $f'\\neq0$, then $f^{-1}$ is differentiable and", "<b>ทฤษฎีบทฟังก์ชันผกผัน</b> ถ้า $f$ หาอนุพันธ์ได้และเป็นฟังก์ชันทางเดียวแท้บนช่วงเปิดโดย $f'\\neq0$ แล้ว $f^{-1}$ หาอนุพันธ์ได้และ", "\\left(f^{-1}\\right)'(y)=\\frac{1}{f'\\big(f^{-1}(y)\\big)}."),
  S("$\\tan:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to\\mathbb{R}$ has $\\tan'=\\sec^{2}>0$. With $y=\\arctan x$, so $\\tan y=x$:", "$\\tan:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to\\mathbb{R}$ มี $\\tan'=\\sec^{2}>0$ ให้ $y=\\arctan x$ คือ $\\tan y=x$:", "\\arctan'(x)=\\frac{1}{\\sec^{2}y}=\\frac{1}{1+\\tan^{2}y}=\\frac{1}{1+x^{2}}."),
  S("$\\sin:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to(-1,1)$ has $\\sin'=\\cos>0$. With $y=\\arcsin x$, $\\cos y>0$, so $\\cos y=+\\sqrt{1-\\sin^{2}y}$:", "$\\sin:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to(-1,1)$ มี $\\sin'=\\cos>0$ ให้ $y=\\arcsin x$ จะได้ $\\cos y>0$ ดังนั้น $\\cos y=+\\sqrt{1-\\sin^{2}y}$:", "\\arcsin'(x)=\\frac{1}{\\cos y}=\\frac{1}{\\sqrt{1-x^{2}}}."),
  S("Chain rule with $\\frac xa$ ($a>0$, so $\\sqrt{a^{2}}=a$):", "กฎลูกโซ่กับ $\\frac xa$ ($a>0$ ดังนั้น $\\sqrt{a^{2}}=a$):", "\\frac{d}{dx}\\frac1a\\arctan\\frac xa=\\frac{1}{a^{2}}\\cdot\\frac{1}{1+\\frac{x^{2}}{a^{2}}}=\\frac{1}{a^{2}+x^{2}},\\qquad \\frac{d}{dx}\\arcsin\\frac xa=\\frac{1}{a\\sqrt{1-\\frac{x^{2}}{a^{2}}}}=\\frac{1}{\\sqrt{a^{2}-x^{2}}}."),
  S("Completing the square is algebra, then apply the first result with the shift $x\\mapsto x+\\frac b2$ (lesson 5). $\\blacksquare$", "การทำกำลังสองสมบูรณ์เป็นพีชคณิต แล้วใช้ผลแรกกับการเลื่อน $x\\mapsto x+\\frac b2$ (บทที่ 5) $\\blacksquare$")],
 [X(r"\int_{0}^{3}\frac{dx}{9+x^{2}}", "pi/12", r"\frac{\pi}{12}", "1/(9+x**2)", ("d", "0", "3"), [r"a=3:\ \left[\tfrac13\arctan\tfrac x3\right]_{0}^{3}=\tfrac13\cdot\tfrac\pi4=\frac{\pi}{12}"]),
  X(r"\int\frac{dx}{x^{2}+2x+5}", "arctan((x+1)/2)/2", r"\frac12\arctan\frac{x+1}{2}+C", "1/(x**2+2*x+5)", ("i", "0", "2"), [r"x^{2}+2x+5=(x+1)^{2}+4", r"\frac12\arctan\frac{x+1}{2}+C"])],
 [P(r"\int_{0}^{2}\frac{dx}{4+x^{2}}", "pi/8", r"\frac{\pi}{8}", "1/(4+x**2)", ("d", "0", "2"), [r"\left[\tfrac12\arctan\tfrac x2\right]_{0}^{2}=\tfrac12\cdot\tfrac\pi4=\frac\pi8"], "$a=2$.", "$a=2$"),
  P(r"\int_{0}^{1}\frac{dx}{\sqrt{4-x^{2}}}", "pi/6", r"\frac{\pi}{6}", "1/sqrt(4-x**2)", ("d", "0", "1"), [r"\left[\arcsin\tfrac x2\right]_{0}^{1}=\arcsin\tfrac12=\frac\pi6"], "$a=2$, arcsin form.", "$a=2$ รูป arcsin"),
  P(r"\int_{-1}^{1}\frac{dx}{x^{2}+2x+2}", "arctan(2)", r"\arctan2", "1/(x**2+2*x+2)", ("d", "-1", "1"), [r"x^{2}+2x+2=(x+1)^{2}+1", r"\left[\arctan(x+1)\right]_{-1}^{1}=\arctan2-0"], "Complete the square.", "ทำเป็นกำลังสองสมบูรณ์"),
  P(r"\int_{0}^{\frac32}\frac{dx}{\sqrt{9-4x^{2}}}", "pi/4", r"\frac{\pi}{4}", "1/sqrt(9-4*x**2)", ("d", "0", "3/2"), [r"\frac{1}{\sqrt{9-4x^{2}}}=\frac{1}{2\sqrt{\frac94-x^{2}}}", r"\left[\tfrac12\arcsin\tfrac{2x}{3}\right]_{0}^{\frac32}=\tfrac12\cdot\tfrac\pi2=\frac\pi4"], "Take out the $4$: $\\sqrt{9-4x^{2}}=2\\sqrt{\\frac94-x^{2}}$.", "ดึง $4$ ออก: $\\sqrt{9-4x^{2}}=2\\sqrt{\\frac94-x^{2}}$"),
  P(r"\int\frac{2x+3}{x^{2}+1}\,dx", "ln(x^2+1)+3arctan(x)", r"\ln\left(x^{2}+1\right)+3\arctan x+C", "(2*x+3)/(x**2+1)", ("i", "0", "2"), [r"\frac{2x}{x^{2}+1}+\frac{3}{x^{2}+1}", r"\ln\left(x^{2}+1\right)+3\arctan x+C"], "Split into an $f'/f$ part and an $\\arctan$ part.", "แยกเป็นส่วน $f'/f$ และส่วน $\\arctan$")]),

L("hyp", "D", "Hyperbolic functions", "ฟังก์ชันไฮเพอร์โบลิก",
 [T("<b>Definitions.</b> $\\sinh x=\\frac{e^{x}-e^{-x}}{2}$, $\\cosh x=\\frac{e^{x}+e^{-x}}{2}$, $\\tanh x=\\frac{\\sinh x}{\\cosh x}$; $\\cosh^{2}x-\\sinh^{2}x=1$.", "<b>นิยาม</b> $\\sinh x=\\frac{e^{x}-e^{-x}}{2}$, $\\cosh x=\\frac{e^{x}+e^{-x}}{2}$, $\\tanh x=\\frac{\\sinh x}{\\cosh x}$ และ $\\cosh^{2}x-\\sinh^{2}x=1$"),
  T("<b>Theorem.</b> $\\int\\cosh x\\,dx=\\sinh x+C$, $\\int\\sinh x\\,dx=\\cosh x+C$, $\\int\\operatorname{sech}^{2}x\\,dx=\\tanh x+C$, and for $a>0$: $$\\int\\frac{dx}{\\sqrt{x^{2}+a^{2}}}=\\operatorname{arcsinh}\\frac xa+C,\\qquad \\int\\frac{dx}{\\sqrt{x^{2}-a^{2}}}=\\operatorname{arccosh}\\frac xa+C\\ (x>a),$$ where $\\operatorname{arcsinh}x=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$ and $\\operatorname{arccosh}x=\\ln\\left(x+\\sqrt{x^{2}-1}\\right)$ $(x\\ge1)$.",
    "<b>ทฤษฎีบท</b> $\\int\\cosh x\\,dx=\\sinh x+C$, $\\int\\sinh x\\,dx=\\cosh x+C$, $\\int\\operatorname{sech}^{2}x\\,dx=\\tanh x+C$ และสำหรับ $a>0$: $$\\int\\frac{dx}{\\sqrt{x^{2}+a^{2}}}=\\operatorname{arcsinh}\\frac xa+C,\\qquad \\int\\frac{dx}{\\sqrt{x^{2}-a^{2}}}=\\operatorname{arccosh}\\frac xa+C\\ (x>a)$$ โดย $\\operatorname{arcsinh}x=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$ และ $\\operatorname{arccosh}x=\\ln\\left(x+\\sqrt{x^{2}-1}\\right)$ $(x\\ge1)$")],
 [S("Differentiate the definitions: $(\\sinh x)'=\\cosh x$, $(\\cosh x)'=\\sinh x$, and by the quotient rule $(\\tanh x)'=\\frac{\\cosh^{2}x-\\sinh^{2}x}{\\cosh^{2}x}=\\operatorname{sech}^{2}x$.", "หาอนุพันธ์จากนิยาม: $(\\sinh x)'=\\cosh x$, $(\\cosh x)'=\\sinh x$ และจากกฎผลหาร $(\\tanh x)'=\\frac{\\cosh^{2}x-\\sinh^{2}x}{\\cosh^{2}x}=\\operatorname{sech}^{2}x$"),
  S("$\\sinh$ is strictly increasing ($\\cosh>0$) from $\\mathbb{R}$ onto $\\mathbb{R}$. Solve $x=\\sinh y$: multiply by $2e^{y}$,", "$\\sinh$ เพิ่มแท้ ($\\cosh>0$) จาก $\\mathbb{R}$ ทั่วถึง $\\mathbb{R}$ แก้ $x=\\sinh y$: คูณด้วย $2e^{y}$", "e^{2y}-2xe^{y}-1=0\\ \\Rightarrow\\ e^{y}=x\\pm\\sqrt{x^{2}+1}."),
  S("Since $e^{y}>0$ and $x-\\sqrt{x^{2}+1}<0$, we must take $+$: $y=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$.", "เนื่องจาก $e^{y}>0$ และ $x-\\sqrt{x^{2}+1}<0$ จึงต้องเลือก $+$: $y=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$"),
  S("$\\cosh$ is strictly increasing from $[0,\\infty)$ onto $[1,\\infty)$. Solving $x=\\cosh y$ gives $e^{y}=x\\pm\\sqrt{x^{2}-1}$; the two roots multiply to $1$, so the $-$ root is $\\le1$, and $y\\ge0$ needs $e^{y}\\ge1$: take $+$.", "$\\cosh$ เพิ่มแท้จาก $[0,\\infty)$ ทั่วถึง $[1,\\infty)$ แก้ $x=\\cosh y$ ได้ $e^{y}=x\\pm\\sqrt{x^{2}-1}$ สองรากคูณกันได้ $1$ รากที่เป็น $-$ จึง $\\le1$ และ $y\\ge0$ ต้องการ $e^{y}\\ge1$: เลือก $+$"),
  S("Inverse function theorem (lesson 13), using $\\cosh y=+\\sqrt{1+\\sinh^{2}y}$ (as $\\cosh>0$) and $\\sinh y=+\\sqrt{\\cosh^{2}y-1}$ for $y>0$:", "ทฤษฎีบทฟังก์ชันผกผัน (บทที่ 13) โดย $\\cosh y=+\\sqrt{1+\\sinh^{2}y}$ (เพราะ $\\cosh>0$) และ $\\sinh y=+\\sqrt{\\cosh^{2}y-1}$ เมื่อ $y>0$:", "\\operatorname{arcsinh}'x=\\frac{1}{\\cosh y}=\\frac{1}{\\sqrt{1+x^{2}}},\\qquad \\operatorname{arccosh}'x=\\frac{1}{\\sinh y}=\\frac{1}{\\sqrt{x^{2}-1}}\\ (x>1)."),
  S("The chain rule with $\\frac xa$ gives the $a$-versions, exactly as in lesson 13. $\\blacksquare$", "กฎลูกโซ่กับ $\\frac xa$ ให้รูปที่มี $a$ เหมือนบทที่ 13 $\\blacksquare$")],
 [X(r"\int_{0}^{\ln2}\cosh x\,dx", "3/4", r"\frac34", "cosh(x)", ("d", "0", "log(2)"), [r"\sinh(\ln2)=\frac{2-\frac12}{2}=\frac34"]),
  X(r"\int_{0}^{4}\frac{dx}{\sqrt{x^{2}+9}}", "ln(3)", r"\ln3", "1/sqrt(x**2+9)", ("d", "0", "4"), [r"\operatorname{arcsinh}\tfrac43=\ln\left(\tfrac43+\sqrt{\tfrac{16}{9}+1}\right)=\ln\left(\tfrac43+\tfrac53\right)=\ln3"])],
 [P(r"\int_{0}^{\ln3}\sinh x\,dx", "2/3", r"\frac23", "sinh(x)", ("d", "0", "log(3)"), [r"\cosh(\ln3)-\cosh0=\frac{3+\frac13}{2}-1=\frac23"], "$\\cosh(\\ln3)=\\frac{3+3^{-1}}{2}$.", "$\\cosh(\\ln3)=\\frac{3+3^{-1}}{2}$"),
  P(r"\int_{0}^{\frac34}\frac{dx}{\sqrt{1+x^{2}}}", "ln(2)", r"\ln2", "1/sqrt(1+x**2)", ("d", "0", "3/4"), [r"\operatorname{arcsinh}\tfrac34=\ln\left(\tfrac34+\tfrac54\right)=\ln2"], "Use the log form of $\\operatorname{arcsinh}$.", "ใช้รูปลอการิทึมของ $\\operatorname{arcsinh}$"),
  P(r"\int_{3}^{5}\frac{dx}{\sqrt{x^{2}-9}}", "ln(3)", r"\ln3", "1/sqrt(x**2-9)", ("d", "3", "5"), [r"\operatorname{arccosh}\tfrac53-\operatorname{arccosh}1=\ln\left(\tfrac53+\tfrac43\right)-0=\ln3"], "$\\operatorname{arccosh}$ form with $a=3$ (improper but convergent at $x=3$).", "รูป $\\operatorname{arccosh}$ โดย $a=3$ (ไม่ตรงแบบแต่ลู่เข้าที่ $x=3$)"),
  P(r"\int_{0}^{\ln2}\tanh x\,dx", "ln(5/4)", r"\ln\frac54", "tanh(x)", ("d", "0", "log(2)"), [r"\tanh=\frac{\sinh}{\cosh}=\frac{f'}{f}", r"\left[\ln\cosh x\right]_{0}^{\ln2}=\ln\frac{2+\frac12}{2}=\ln\frac54"], "$f'/f$ with $f=\\cosh x$.", "$f'/f$ โดย $f=\\cosh x$"),
  P(r"\int_{0}^{2}\frac{dx}{\sqrt{x^{2}+4x+8}}", "ln((2+sqrt(5))/(1+sqrt(2)))", r"\ln\frac{2+\sqrt5}{1+\sqrt2}", "1/sqrt(x**2+4*x+8)", ("d", "0", "2"), [r"x^{2}+4x+8=(x+2)^{2}+4", r"\left[\operatorname{arcsinh}\tfrac{x+2}{2}\right]_{0}^{2}=\operatorname{arcsinh}2-\operatorname{arcsinh}1", r"=\ln\frac{2+\sqrt5}{1+\sqrt2}"], "Complete the square, then $\\operatorname{arcsinh}$.", "ทำกำลังสองสมบูรณ์ แล้วใช้ $\\operatorname{arcsinh}$")]),

L("tsub", "D", "Trig and hyperbolic substitutions", "การแทนค่าด้วยตรีโกณและไฮเพอร์โบลิก",
 [T("<b>Theorem.</b> For $a>0$: $$\\int\\sqrt{a^{2}-x^{2}}\\,dx=\\frac12\\left(x\\sqrt{a^{2}-x^{2}}+a^{2}\\arcsin\\frac xa\\right)+C\\quad\\text{on }[-a,a],$$ $$\\int\\sqrt{x^{2}+a^{2}}\\,dx=\\frac12\\left(x\\sqrt{x^{2}+a^{2}}+a^{2}\\operatorname{arcsinh}\\frac xa\\right)+C.$$",
    "<b>ทฤษฎีบท</b> สำหรับ $a>0$: $$\\int\\sqrt{a^{2}-x^{2}}\\,dx=\\frac12\\left(x\\sqrt{a^{2}-x^{2}}+a^{2}\\arcsin\\frac xa\\right)+C\\quad\\text{บน }[-a,a]$$ $$\\int\\sqrt{x^{2}+a^{2}}\\,dx=\\frac12\\left(x\\sqrt{x^{2}+a^{2}}+a^{2}\\operatorname{arcsinh}\\frac xa\\right)+C$$"),
  T("Guide: $\\sqrt{a^{2}-x^{2}}\\to x=a\\sin\\theta$; $\\ a^{2}+x^{2}\\to x=a\\tan\\theta$ or $a\\sinh u$; $\\ \\sqrt{x^{2}-a^{2}}\\to x=a\\cosh u$.", "แนวทาง: $\\sqrt{a^{2}-x^{2}}\\to x=a\\sin\\theta$; $\\ a^{2}+x^{2}\\to x=a\\tan\\theta$ หรือ $a\\sinh u$; $\\ \\sqrt{x^{2}-a^{2}}\\to x=a\\cosh u$")],
 [S("Inverse substitution (lesson 9): $\\varphi(\\theta)=a\\sin\\theta$ is $C^{1}$ and a bijection from $\\left[-\\tfrac\\pi2,\\tfrac\\pi2\\right]$ onto $[-a,a]$, with $\\varphi'(\\theta)=a\\cos\\theta$.", "การแทนค่าผกผัน (บทที่ 9): $\\varphi(\\theta)=a\\sin\\theta$ เป็น $C^{1}$ และเป็นฟังก์ชันหนึ่งต่อหนึ่งทั่วถึงจาก $\\left[-\\tfrac\\pi2,\\tfrac\\pi2\\right]$ ไป $[-a,a]$ โดย $\\varphi'(\\theta)=a\\cos\\theta$"),
  S("On this range $\\cos\\theta\\ge0$, so the square root has no sign problem:", "ในช่วงนี้ $\\cos\\theta\\ge0$ รากที่สองจึงไม่มีปัญหาเรื่องเครื่องหมาย:", "\\sqrt{a^{2}-a^{2}\\sin^{2}\\theta}=a|\\cos\\theta|=a\\cos\\theta."),
  S("Hence, using lesson 8,", "ดังนั้นจากบทที่ 8", "\\int\\sqrt{a^{2}-x^{2}}\\,dx=\\int a^{2}\\cos^{2}\\theta\\,d\\theta=\\frac{a^{2}}{2}\\left(\\theta+\\sin\\theta\\cos\\theta\\right)+C."),
  S("Back-substitute $\\theta=\\arcsin\\frac xa$, $\\sin\\theta=\\frac xa$, $\\cos\\theta=\\frac{\\sqrt{a^{2}-x^{2}}}{a}$ to get the formula (check: differentiate it).", "แทนกลับ $\\theta=\\arcsin\\frac xa$, $\\sin\\theta=\\frac xa$, $\\cos\\theta=\\frac{\\sqrt{a^{2}-x^{2}}}{a}$ ได้สูตร (ตรวจโดยหาอนุพันธ์)"),
  S("Second formula: $x=a\\sinh u$ is a $C^{1}$ bijection $\\mathbb{R}\\to\\mathbb{R}$, $\\sqrt{x^{2}+a^{2}}=a\\cosh u$ (as $\\cosh>0$), so", "สูตรที่สอง: $x=a\\sinh u$ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}\\to\\mathbb{R}$ และ $\\sqrt{x^{2}+a^{2}}=a\\cosh u$ (เพราะ $\\cosh>0$) ดังนั้น", "\\int a^{2}\\cosh^{2}u\\,du=\\frac{a^{2}}{2}\\left(u+\\sinh u\\cosh u\\right)+C,\\ \\text{then }u=\\operatorname{arcsinh}\\tfrac xa.\\ \\blacksquare")],
 [X(r"\int_{0}^{2}\sqrt{4-x^{2}}\,dx", "pi", r"\pi", "sqrt(4-x**2)", ("d", "0", "2"), [r"\tfrac12\left(0+4\cdot\tfrac\pi2\right)-0=\pi", r"\text{(a quarter of a circle of radius }2)"]),
  X(r"\int_{0}^{1}\frac{x^{2}}{\sqrt{1-x^{2}}}\,dx", "pi/4", r"\frac{\pi}{4}", "x**2/sqrt(1-x**2)", ("d", "0", "1"), [r"x=\sin\theta:\ \int_{0}^{\frac\pi2}\frac{\sin^{2}\theta}{\cos\theta}\cos\theta\,d\theta", r"=\int_{0}^{\frac\pi2}\sin^{2}\theta\,d\theta=\frac\pi4"])],
 [P(r"\int_{0}^{3}\sqrt{9-x^{2}}\,dx", "9pi/4", r"\frac{9\pi}{4}", "sqrt(9-x**2)", ("d", "0", "3"), [r"\tfrac12\left(0+9\cdot\tfrac\pi2\right)=\frac{9\pi}{4}"], "$a=3$, or: a quarter circle.", "$a=3$ หรือคิดเป็นหนึ่งในสี่วงกลม"),
  P(r"\int_{0}^{1}\sqrt{4-x^{2}}\,dx", "sqrt(3)/2+pi/3", r"\frac{\sqrt3}{2}+\frac{\pi}{3}", "sqrt(4-x**2)", ("d", "0", "1"), [r"\tfrac12\left(1\cdot\sqrt3+4\arcsin\tfrac12\right)=\frac{\sqrt3}{2}+\frac{\pi}{3}"], "Use the formula with $a=2$, $x=1$.", "ใช้สูตรโดย $a=2$, $x=1$"),
  P(r"\int_{0}^{1}\frac{dx}{\left(1+x^{2}\right)^{\frac32}}", "sqrt(2)/2", r"\frac{\sqrt2}{2}", "1/(1+x**2)**1.5", ("d", "0", "1"), [r"x=\tan\theta,\ dx=\sec^{2}\theta\,d\theta:\ \int_{0}^{\frac\pi4}\cos\theta\,d\theta", r"=\sin\tfrac\pi4=\frac{\sqrt2}{2}"], "Let $x=\\tan\\theta$: $1+\\tan^{2}\\theta=\\sec^{2}\\theta$.", "ให้ $x=\\tan\\theta$: $1+\\tan^{2}\\theta=\\sec^{2}\\theta$"),
  P(r"\int_{0}^{\frac12}\frac{x^{2}}{\sqrt{1-x^{2}}}\,dx", "pi/12-sqrt(3)/8", r"\frac{\pi}{12}-\frac{\sqrt3}{8}", "x**2/sqrt(1-x**2)", ("d", "0", "1/2"), [r"x=\sin\theta:\ \int_{0}^{\frac\pi6}\sin^{2}\theta\,d\theta", r"=\left[\tfrac\theta2-\tfrac{\sin2\theta}{4}\right]_{0}^{\frac\pi6}=\frac{\pi}{12}-\frac{\sqrt3}{8}"], "Let $x=\\sin\\theta$; the upper limit becomes $\\frac\\pi6$.", "ให้ $x=\\sin\\theta$ ขอบบนเป็น $\\frac\\pi6$"),
  P(r"\int_{0}^{1}\sqrt{x^{2}+1}\,dx", "(sqrt(2)+ln(1+sqrt(2)))/2", r"\frac{\sqrt2+\ln\left(1+\sqrt2\right)}{2}", "sqrt(x**2+1)", ("d", "0", "1"), [r"\tfrac12\left(1\cdot\sqrt2+\operatorname{arcsinh}1\right)", r"=\frac{\sqrt2+\ln\left(1+\sqrt2\right)}{2}"], "Second formula with $a=1$.", "สูตรที่สองโดย $a=1$")]),

L("red", "D", "Reduction formulae", "สูตรลดทอน",
 [T("<b>Theorem.</b> Let $I_n=\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{n}x\\,dx$. Then $I_0=\\frac\\pi2$, $I_1=1$ and $$I_n=\\frac{n-1}{n}I_{n-2}\\quad(n\\ge2).$$ Also $J_n=\\displaystyle\\int_{0}^{1}x^{n}e^{x}\\,dx$ satisfies $J_0=e-1$ and $J_n=e-nJ_{n-1}$ $(n\\ge1)$.",
    "<b>ทฤษฎีบท</b> ให้ $I_n=\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{n}x\\,dx$ แล้ว $I_0=\\frac\\pi2$, $I_1=1$ และ $$I_n=\\frac{n-1}{n}I_{n-2}\\quad(n\\ge2)$$ และ $J_n=\\displaystyle\\int_{0}^{1}x^{n}e^{x}\\,dx$ มี $J_0=e-1$ และ $J_n=e-nJ_{n-1}$ $(n\\ge1)$"),
  T("Consequently $I_{2m}=\\dfrac{(2m-1)(2m-3)\\cdots1}{(2m)(2m-2)\\cdots2}\\cdot\\dfrac\\pi2$ and $I_{2m+1}=\\dfrac{(2m)(2m-2)\\cdots2}{(2m+1)(2m-1)\\cdots3}$ (Wallis).", "ดังนั้น $I_{2m}=\\dfrac{(2m-1)(2m-3)\\cdots1}{(2m)(2m-2)\\cdots2}\\cdot\\dfrac\\pi2$ และ $I_{2m+1}=\\dfrac{(2m)(2m-2)\\cdots2}{(2m+1)(2m-1)\\cdots3}$ (วอลลิส)")],
 [S("For $n\\ge2$ integrate by parts (lesson 10) with $u=\\sin^{n-1}x$, $v'=\\sin x$, so $u'=(n-1)\\sin^{n-2}x\\cos x$, $v=-\\cos x$:", "สำหรับ $n\\ge2$ อินทิเกรตทีละส่วน (บทที่ 10) โดย $u=\\sin^{n-1}x$, $v'=\\sin x$ ดังนั้น $u'=(n-1)\\sin^{n-2}x\\cos x$, $v=-\\cos x$:", "I_n=\\Big[-\\sin^{n-1}x\\cos x\\Big]_{0}^{\\frac\\pi2}+(n-1)\\int_{0}^{\\frac\\pi2}\\sin^{n-2}x\\cos^{2}x\\,dx."),
  S("The bracket is $0$ at both ends (as $n-1\\ge1$). Use $\\cos^{2}x=1-\\sin^{2}x$:", "วงเล็บเป็น $0$ ทั้งสองปลาย (เพราะ $n-1\\ge1$) ใช้ $\\cos^{2}x=1-\\sin^{2}x$:", "I_n=(n-1)\\left(I_{n-2}-I_n\\right)\\ \\Rightarrow\\ nI_n=(n-1)I_{n-2}."),
  S("$I_0=\\int_{0}^{\\pi/2}1\\,dx=\\frac\\pi2$ and $I_1=[-\\cos x]_{0}^{\\pi/2}=1$; the Wallis products follow by induction on $m$.", "$I_0=\\int_{0}^{\\pi/2}1\\,dx=\\frac\\pi2$ และ $I_1=[-\\cos x]_{0}^{\\pi/2}=1$ ผลคูณวอลลิสได้จากอุปนัยบน $m$"),
  S("For $J_n$: parts with $u=x^{n}$, $v'=e^{x}$:", "สำหรับ $J_n$: ทีละส่วนโดย $u=x^{n}$, $v'=e^{x}$:", "J_n=\\Big[x^{n}e^{x}\\Big]_{0}^{1}-n\\int_{0}^{1}x^{n-1}e^{x}\\,dx=e-nJ_{n-1}.\\ \\blacksquare")],
 [X(r"\int_{0}^{\frac\pi2}\sin^{4}x\,dx", "3pi/16", r"\frac{3\pi}{16}", "sin(x)**4", ("d", "0", "pi/2"), [r"I_4=\tfrac34I_2=\tfrac34\cdot\tfrac12I_0=\tfrac38\cdot\tfrac\pi2=\frac{3\pi}{16}"]),
  X(r"\int_{0}^{1}x^{2}e^{x}\,dx", "e-2", r"e-2", "x**2*exp(x)", ("d", "0", "1"), [r"J_1=e-J_0=1,\quad J_2=e-2J_1=e-2"])],
 [P(r"\int_{0}^{\frac\pi2}\sin^{5}x\,dx", "8/15", r"\frac{8}{15}", "sin(x)**5", ("d", "0", "pi/2"), [r"I_5=\tfrac45I_3=\tfrac45\cdot\tfrac23I_1=\frac{8}{15}"], "$I_5=\\frac45I_3$, $I_3=\\frac23I_1$.", "$I_5=\\frac45I_3$, $I_3=\\frac23I_1$"),
  P(r"\int_{0}^{\frac\pi2}\sin^{6}x\,dx", "5pi/32", r"\frac{5\pi}{32}", "sin(x)**6", ("d", "0", "pi/2"), [r"I_6=\tfrac56\cdot\tfrac34\cdot\tfrac12\cdot\tfrac\pi2=\frac{5\pi}{32}"], "Go down to $I_0=\\frac\\pi2$.", "ลดลงไปถึง $I_0=\\frac\\pi2$"),
  P(r"\int_{0}^{\frac\pi2}\cos^{4}x\,dx", "3pi/16", r"\frac{3\pi}{16}", "cos(x)**4", ("d", "0", "pi/2"), [r"x=\tfrac\pi2-u\text{ turns }\cos^{4}x\text{ into }\sin^{4}u", r"=I_4=\frac{3\pi}{16}"], "Substitute $x=\\frac\\pi2-u$: it becomes $I_4$.", "แทน $x=\\frac\\pi2-u$ จะกลายเป็น $I_4$"),
  P(r"\int_{0}^{1}x^{3}e^{x}\,dx", "6-2e", r"6-2e", "x**3*exp(x)", ("d", "0", "1"), [r"J_3=e-3J_2=e-3(e-2)=6-2e"], "Use $J_2=e-2$ from the example.", "ใช้ $J_2=e-2$ จากตัวอย่าง"),
  P(r"\int_{0}^{\frac\pi2}\sin^{7}x\,dx", "16/35", r"\frac{16}{35}", "sin(x)**7", ("d", "0", "pi/2"), [r"I_7=\tfrac67\cdot\tfrac45\cdot\tfrac23\cdot1=\frac{16}{35}"], "Odd power: end at $I_1=1$.", "กำลังคี่: จบที่ $I_1=1$")]),
]
